// Node's own resolution rule sends this require to vt2-init-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// A private helper that exists only to share the vulnerable export's
// spelling (RWF-011). Nothing publishes it, nothing calls it, and it is
// declared BEFORE everything real -- so both a same-file bare-name search
// and a "first function in the file" heuristic land here.
function dangerousOp(input) {
  return "decoy:" + input;
}

// The branch that reaches the vulnerable package. Nothing in this file
// calls it: the ONLY way it ever runs is by being this module's exported
// value.
function fastPath(input) {
  return dep.dangerousOp(input);
}

// The branch that does not.
function slowPath(input) {
  return "slow:" + input;
}

// The RWF-022 callee. Its entire body is a single unconditional `return` of
// a numeric literal. It is NOT abrupt -- it completes, every time, and hands
// back `1`. RWF-016's `cannotCompleteNormally` refuses it, correctly, and
// RWF-020 therefore has nothing to fire on. What makes it decisive is
// nothing about the CALL and everything about the VALUE: `1` is neither
// `null` nor a constructor.
function notAConstructor() {
  return 1;
}

// Heritage callees that return values which ARE valid superclasses. These
// are the controls that separate RWF-022's rule from a crude "any call in an
// extends clause" rule -- and from a value classifier careless enough to
// treat `null` as an invalid superclass, which it is not.
function makeBase() {
  return class Base {};
}

function makeCtor() {
  return function Ctor() {};
}

function makeNull() {
  return null;
}

// TWO returns, one of them the invalid `1`. Not definitely anything -- the
// flag is a runtime value. An analyzer that classifies this as definitely
// invalid is guessing, and at runtime this particular call returns a class.
function maybeBase(flag) {
  if (flag) {
    return makeBase();
  }
  return 1;
}

// A factory that is REASSIGNED below its declaration, so no return-value
// summary read off the declaration is still valid at the call site
// (RWF-013/013b). After the reassignment it returns a class.
let rebound = function () {
  return 1;
};

// A same-name decoy nested inside a function that is never called at module
// scope. Real JS lexical scoping never resolves the module-scope call below
// to this one, and the deferred body never runs at load time either.
function configure() {
  function notAConstructor() {
    return class Configured {};
  }
  // A class carrying the exact RWF-022 shape, DEFERRED inside a function
  // body: `configure` is never called at module scope, so this class is
  // never evaluated during module evaluation and must poison nothing.
  class Deferred extends notAConstructor() {}
  return Deferred;
}

// An ALIAS and a MEMBER callee, neither of which this analyzer resolves.
// Both are deferred inside an uncalled function so that refusing to resolve
// them costs nothing here, and so that an analyzer tempted to chase either
// has something to be wrong about.
const alias = notAConstructor;
const holder = { make: notAConstructor };

function probeIndirect() {
  class ViaAlias extends alias() {}
  class ViaMember extends holder.make() {}
  return [ViaAlias, ViaMember];
}

// Heritage clauses in the shapes that genuinely do NOT end module
// evaluation, all evaluated at module scope. Each returns a value that IS a
// valid superclass, or is one directly.
class FromClass extends makeBase() {}
class FromFunction extends makeCtor() {}
class FromNull extends makeNull() {}
class Rootless extends null {}
class FromMaybe extends maybeBase(true) {}

rebound = function () {
  return class Rebound {};
};
class FromRebound extends rebound() {}

// A class with the invalid-returning call in every position the language
// DEFERS: an instance field's VALUE and a method BODY. Evaluating this
// definition installs an initializer and defines a method and executes
// neither -- and neither is a heritage position anyway.
class Probe extends makeBase() {
  ready = notAConstructor();
  lazy() {
    return notAConstructor();
  }
}

if (process.env.VT2_MODE === "fast") {
  module.exports = fastPath;
  // The RWF-022 shape. The class body is EMPTY and the heritage call
  // RETURNS: `notAConstructor()` completes and hands back `1`.
  // ClassDefinitionEvaluation then fails its own heritage validation --
  // `1` is neither `null` nor a constructor -- and throws
  // `TypeError: Class extends value 1 is not a constructor or null`.
  // `Mode` is never bound, and module evaluation on this branch ends here.
  class Mode extends notAConstructor() {}
}

// Reached on every OTHER load, and on no load where the branch above was
// taken. Syntactically this is exactly what RWF-014 accepted: a bare
// identifier assigned by an unconditional top-level statement, last in the
// file, with no deferred write anywhere -- and RWF-015's return/throw
// cutoff, RWF-016's bare-call cutoff, RWF-017's variable-initializer
// cutoff, RWF-018's static-field cutoff, RWF-019's computed-key cutoff and
// RWF-020's throwing-heritage cutoff all find nothing here to object to
// either: the file contains no module-scope `return`/`throw`, no bare
// `notAConstructor();` statement, no `const x = notAConstructor();`
// declaration, no `static` field at all, no computed key at all, and no
// heritage call whose callee can only throw.
module.exports = slowPath;

void configure;
void probeIndirect;
void FromClass;
void FromFunction;
void FromNull;
void Rootless;
void FromMaybe;
void FromRebound;
void Probe;
